package com.immersio.subscriptions.service; import com.immersio.subscriptions.api.dto.*; import com.immersio.subscriptions.domain.*; import com.immersio.subscriptions.repository.*; import com.immersio.users.repository.UserRepository; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class SubscriptionService {private final PaymentTransactionRepository payments; private final UserRepository users; public SubscriptionService(PaymentTransactionRepository p,UserRepository u){payments=p;users=u;} public CreatePaymentResponse createPaymentUrl(UUID u,CreatePaymentRequest r){String ref="IMR-"+UUID.randomUUID();payments.save(new PaymentTransaction(ref,u,r.tier(),r.billingCycle(),r.resolvedAmount()));return new CreatePaymentResponse("/api/subscription/payos-return?txnRef="+ref+"&status=PAID",ref);} public PaymentReturnResult handlePaymentReturn(String ref,String status){var p=payments.findByTxnRef(ref).orElseThrow();boolean success="PAID".equalsIgnoreCase(status);if(success){p.paid();users.findById(p.getUserId()).ifPresent(x->x.updateSubscription(p.getTier(),Instant.now().plus(30,java.time.temporal.ChronoUnit.DAYS)));} else p.fail(status);payments.save(p);return new PaymentReturnResult(success,"Payment "+p.getStatus().toLowerCase(),p.getTier(),p.getBillingCycle(),p.getAmount());} public void handlePayOsWebhook(String ref,String status){handlePaymentReturn(ref,status);} public void upgradeSubscription(UUID u,UpgradeSubscriptionRequest r){users.findById(u).orElseThrow().updateSubscription(r.tier(),Instant.now().plus(30,java.time.temporal.ChronoUnit.DAYS));}}
